        <script>
        // ==================== КОНСТАНТЫ ====================
        const WS_URL = 'wss://mandala-engineer-chat.onrender.com/ws';
        const API_BASE = 'https://mandala-engineer-chat.onrender.com'; // базовый URL для API
        const GITHUB_REPO = 'voodoomushroomzzz-source/mandala-core';

        // Глобальные переменные
        let chats = [];
        let currentChatId = null;
        let nextChatId = 1;
        let ws = null;
        let pendingFiles = [];
        let messageBuffer = '';
        let currentMessageDiv = null;
        let currentPatch = null;
        let editor = null; // для Monaco

        // DOM элементы
        const statusDot = document.getElementById('statusDot');
        const messagesEl = document.getElementById('messages');
        const inputEl = document.getElementById('messageInput');
        const sendBtn = document.getElementById('sendBtn');
        const thinkingEl = document.getElementById('thinking');
        const seedsGrid = document.getElementById('seedsGrid');
        const filePreview = document.getElementById('filePreview');
        const fileNameEl = document.getElementById('fileName');
        const filePercentEl = document.getElementById('filePercent');
        const fileProgressBar = document.getElementById('fileProgressBar');
        const chatList = document.getElementById('chatList');
        const fileTree = document.getElementById('file-tree');
        const currentFilePath = document.getElementById('current-file-path');
        const saveFileBtn = document.getElementById('save-file-btn');

        // ==================== ИНИЦИАЛИЗАЦИЯ MONACO ====================
        require.config({ paths: { vs: 'https://cdn.jsdelivr.net/npm/monaco-editor@0.52.2/min/vs' } });
        require(['vs/editor/editor.main'], function() {
            editor = monaco.editor.create(document.getElementById('monaco-editor'), {
                value: '// Выберите файл для редактирования',
                language: 'text',
                theme: 'vs-dark',
                automaticLayout: true,
                minimap: { enabled: false }
            });
        });

        // ==================== ЗАГРУЗКА ЧАТОВ ====================
        function loadChats() {
            const saved = localStorage.getItem('mandala_chats');
            if (saved) {
                try {
                    chats = JSON.parse(saved);
                    nextChatId = Math.max(...chats.map(c => parseInt(c.id.replace('chat_', ''))), 0) + 1;
                } catch (e) {
                    chats = [];
                }
            }
            renderChatList();
        }

        function saveChats() {
            localStorage.setItem('mandala_chats', JSON.stringify(chats));
            chats.forEach(chat => {
                if (chat.messages && chat.messages.length) {
                    localStorage.setItem(`chat_${chat.id}_messages`, JSON.stringify(chat.messages));
                }
            });
        }

        function renderChatList() {
            chatList.innerHTML = chats.map(chat => `
                <div class="chat-item ${chat.id === currentChatId ? 'active' : ''}" onclick="switchChat('${chat.id}')">
                    <span class="chat-item-title">${escapeHtml(chat.name)}</span>
                    <div class="chat-item-actions">
                        <button class="chat-item-action" onclick="renameChat('${chat.id}', event)">✎</button>
                        <button class="chat-item-action delete" onclick="deleteChat('${chat.id}', event)">×</button>
                    </div>
                </div>
            `).join('');
        }

        function createNewChat(name = null) {
            const defaultName = name || `Чат ${nextChatId}`;
            const chatId = 'chat_' + (nextChatId++);
            const newChat = { id: chatId, name: defaultName, created: Date.now(), messages: [] };
            chats.push(newChat);
            saveChats();
            renderChatList();
            switchChat(chatId);
        }

        function switchChat(chatId) {
            if (currentChatId === chatId) return;
            if (currentChatId) saveCurrentChatMessages();
            currentChatId = chatId;
            localStorage.setItem('current_chat_id', chatId);
            const chat = chats.find(c => c.id === chatId);
            if (chat) {
                const savedMessages = localStorage.getItem(`chat_${chatId}_messages`);
                chat.messages = savedMessages ? JSON.parse(savedMessages) : [];
                messagesEl.innerHTML = '';
                if (chat.messages.length > 0) {
                    chat.messages.forEach(msg => {
                        if (msg.role === 'user') addUserMessage(msg.content, false);
                        else if (msg.role === 'assistant') appendFullMessage(msg.content, false);
                        else if (msg.role === 'system') addSystemMessage(msg.content, false);
                    });
                } else {
                    addSystemMessage('🌱 Новый чат. Добро пожаловать!', false);
                }
                renderChatList();
            }
        }

        function saveCurrentChatMessages() {
            if (!currentChatId) return;
            const chat = chats.find(c => c.id === currentChatId);
            if (chat) {
                const messages = [];
                document.querySelectorAll('.msg').forEach(msgEl => {
                    const role = msgEl.classList.contains('user') ? 'user' : 
                                msgEl.classList.contains('sys') ? 'system' : 'assistant';
                    const content = msgEl.querySelector('.bub').innerText;
                    messages.push({ role, content });
                });
                chat.messages = messages;
                localStorage.setItem(`chat_${currentChatId}_messages`, JSON.stringify(messages));
            }
        }

        function renameChat(chatId, event) {
            event.stopPropagation();
            const chat = chats.find(c => c.id === chatId);
            if (!chat) return;
            document.getElementById('renameInput').value = chat.name;
            document.getElementById('renameModal').classList.add('active');
            document.getElementById('confirmRenameBtn').dataset.chatId = chatId;
        }

        function closeRenameModal() {
            document.getElementById('renameModal').classList.remove('active');
        }

        function confirmRename() {
            const chatId = document.getElementById('confirmRenameBtn').dataset.chatId;
            const newName = document.getElementById('renameInput').value.trim();
            if (!chatId || !newName) return;
            const chat = chats.find(c => c.id === chatId);
            if (chat) {
                chat.name = newName;
                saveChats();
                renderChatList();
            }
            closeRenameModal();
        }

        function deleteChat(chatId, event) {
            event.stopPropagation();
            if (chats.length <= 1) {
                showToast('Нельзя удалить последний чат', 'error');
                return;
            }
            const index = chats.findIndex(c => c.id === chatId);
            if (index !== -1) {
                localStorage.removeItem(`chat_${chatId}_messages`);
                chats.splice(index, 1);
                if (currentChatId === chatId) switchChat(chats[0].id);
                else renderChatList();
                saveChats();
            }
        }

        // ==================== WEBSOCKET ====================
        function connect() {
            updateStatus('connecting');
            ws = new WebSocket(WS_URL);
            ws.onopen = () => ws.send(JSON.stringify({ type: 'init', session_id: currentChatId }));
            ws.onmessage = (e) => { try { handleMessage(JSON.parse(e.data)); } catch (ex) { console.error(ex); } };
            ws.onclose = () => { updateStatus('error'); showToast('◈ соединение разорвано', 'error'); setTimeout(connect, 3000); };
            ws.onerror = () => updateStatus('error');
        }

        function updateStatus(state) {
            statusDot.className = 'orb-dot';
            if (state === 'connected') {
                statusDot.style.background = 'var(--green-2)';
                statusDot.style.boxShadow = '0 0 10px var(--green-2), 0 0 20px rgba(16,185,129,0.3)';
            } else if (state === 'connecting') {
                statusDot.style.background = 'var(--violet-soft)';
                statusDot.style.boxShadow = '0 0 8px var(--violet-soft)';
            } else {
                statusDot.style.background = '#f43f5e';
                statusDot.style.boxShadow = '0 0 12px #f43f5e';
            }
        }

        function handleMessage(data) {
            switch(data.type) {
                case 'connected':
                    updateStatus('connected');
                    break;
                case 'history':
                    // Бэкенд восстановил сессию из GitHub — рендерим историю
                    // Пропускаем protected служебные сообщения (инъекция ядра)
                    messagesEl.innerHTML = '';
                    (data.messages || []).forEach(msg => {
                        if (msg.role === 'user') addUserMessage(msg.content, false);
                        else if (msg.role === 'assistant') appendFullMessage(msg.content, false);
                    });
                    scrollToBottom();
                    break;
                case 'system':
                    addSystemMessage(data.text);
                    break;
                case 'stream':
                    handleStream(data.content);
                    break;
                case 'done':
                    finishMessage();
                    break;
                case 'error':
                    showToast(data.text, 'error');
                    hideThinking();
                    finishMessage();
                    break;
                case 'module_direct':
                    showToast(`◈ модуль ${data.name} получен`, 'success');
                    const formatted = `**Модуль ${data.name}:**\n\`\`\`json\n${data.content}\n\`\`\``;
                    appendFullMessage(formatted, true);
                    break;
                case 'modules_refreshed':
                    showToast(`◈ обновлено ${data.count} модулей`, 'success');
                    break;
                case 'file_processed':
                    // Показываем подтверждение в индикаторе
                    fileNameEl.textContent = `✅ ${data.summary}`;
                    fileProgressBar.style.width = '100%';
                    filePercentEl.textContent = '100%';
                    addSystemMessage(data.summary);
                    break;
                case 'patch_result':
                    handlePatchResult(data.results);
                    break;
                case 'resonance':
                    updateResonance(data.value, data.level);
                    break;
                case 'pong':
                    break;
                case 'observer_state':
                    setObserverState(data.active);
                    break;
                case 'observer_thinking':
                    showObserverThinking();
                    break;
                case 'observer_message':
                    hideObserverThinking();
                    addObserverMessage(data.content);
                    break;
                case 'observer_error':
                    hideObserverThinking();
                    showToast('◬ Claude-наблюдатель не ответил', 'error');
                    break;
            }
        }

        // ==================== СООБЩЕНИЯ ====================
        function createMessageElement(role) {
            const div = document.createElement('div');
            div.className = `msg ${role}`;
            const iconSvg = role === 'user' 
                ? '<svg viewBox="0 0 30 30" fill="none"><circle cx="15" cy="15" r="13" stroke="#7c3aed" stroke-width="0.8" opacity="0.4"/><circle cx="15" cy="15" r="6" stroke="#7c3aed" stroke-width="0.8" fill="rgba(124,58,237,0.08)"/><circle cx="15" cy="15" r="2" fill="#a78bfa" opacity="0.6"/></svg>'
                : '<svg viewBox="0 0 30 30" fill="none"><circle cx="15" cy="15" r="7" stroke="#10b981" stroke-width="0.8"/><circle cx="15" cy="8"  r="7" stroke="#10b981" stroke-width="0.8" opacity="0.5"/><circle cx="15" cy="22" r="7" stroke="#10b981" stroke-width="0.8" opacity="0.5"/><circle cx="21.06" cy="11.5" r="7" stroke="#10b981" stroke-width="0.8" opacity="0.5"/><circle cx="21.06" cy="18.5" r="7" stroke="#10b981" stroke-width="0.8" opacity="0.5"/><circle cx="8.94" cy="11.5"  r="7" stroke="#10b981" stroke-width="0.8" opacity="0.5"/><circle cx="8.94" cy="18.5"  r="7" stroke="#10b981" stroke-width="0.8" opacity="0.5"/><circle cx="15" cy="15" r="2" fill="#34d399" opacity="0.9"/></svg>';
            const name = role === 'user' ? 'вы' : (role === 'assistant' ? 'СР' : 'система');
            div.innerHTML = `
                <div class="av">${iconSvg}</div>
                <div class="mbody">
                    <div class="mname">${name}</div>
                    <div class="bub"></div>
                </div>
            `;
            return div;
        }

        function addUserMessage(text, save = true) {
            const div = createMessageElement('user');
            // Детектируем файловые сообщения из истории
            const fileMatch = text.match(/^\[Файл загружен: (.+?)\]\n```[\s\S]*$/);
            const fileMatchSimple = text.match(/^\[Загружен файл: (.+?)\]$/);
            const patchMatch = text.match(/^\[Патч: (.+?)\]$/);
            const commentMatch = text.match(/^\[Комментарий к файлу (.+?)\]: ([\s\S]*)$/);
            const coreMatch = text.match(/^\[ЯДРО МАНДАЛЫ ЗАГРУЖЕНО\]/);
            const observerMatch = text.match(/^\[Комментарий внешнего наблюдателя Claude/);

            if (coreMatch || observerMatch) {
                // Системные инъекции — не показываем
                return;
            } else if (fileMatch || fileMatchSimple) {
                const fname = (fileMatch && fileMatch[1]) || (fileMatchSimple && fileMatchSimple[1]);
                div.querySelector('.bub').innerHTML = `<span style="display:inline-flex;align-items:center;gap:8px;padding:6px 12px;background:var(--surface-2);border:1px solid var(--line-2);border-radius:6px;font-family:var(--mono);font-size:11px;color:var(--green-bright);">📎 ${escapeHtml(fname)}</span>`;
            } else if (patchMatch) {
                div.querySelector('.bub').innerHTML = `<span style="display:inline-flex;align-items:center;gap:8px;padding:6px 12px;background:var(--surface-2);border:1px solid rgba(167,139,250,0.3);border-radius:6px;font-family:var(--mono);font-size:11px;color:var(--violet-soft);">📦 ${escapeHtml(patchMatch[1])}</span>`;
            } else if (commentMatch) {
                div.querySelector('.bub').textContent = commentMatch[2] || text;
            } else {
                div.querySelector('.bub').textContent = text;
            }
            messagesEl.appendChild(div);
            scrollToBottom();
            if (save) saveCurrentChatMessages();
        }

        function addSystemMessage(text, save = true) {
            const div = document.createElement('div');
            div.className = 'msg sys';
            div.innerHTML = `<div class="bub">${text}</div>`;
            messagesEl.appendChild(div);
            scrollToBottom();
            if (save) saveCurrentChatMessages();
        }

        function appendFullMessage(text, save = true) {
            const div = createMessageElement('assistant');
            let html = escapeHtml(text);
            html = html.replace(/```(\w*)\n([\s\S]*?)```/g, (match, lang, code) => renderCodeBlock(lang, code, true));
            html = html.replace(/`([^`]+)`/g, '<code>$1</code>');
            html = html.replace(/\*\*([^*]+)\*\*/g, '<strong style="color: var(--green-bright);">$1</strong>');
            html = html.replace(/\n/g, '<br>');
            div.querySelector('.bub').innerHTML = html;
            messagesEl.appendChild(div);
            scrollToBottom();
            if (save) saveCurrentChatMessages();
        }

        function handleStream(content) {
            if (!currentMessageDiv) {
                currentMessageDiv = createMessageElement('assistant');
                messagesEl.appendChild(currentMessageDiv);
            }
            messageBuffer += content;
            const bub = currentMessageDiv.querySelector('.bub');
            let html = escapeHtml(messageBuffer);
            html = html.replace(/```(\w*)\n([\s\S]*?)```/g, (match, lang, code) => renderCodeBlock(lang, code, true));
            html = html.replace(/```(\w*)\n([\s\S]*)$/, (match, lang, code) => {
                if (!messageBuffer.includes('```', messageBuffer.lastIndexOf('```')+3)) return renderCodeBlock(lang, code, false);
                return match;
            });
            html = html.replace(/`([^`]+)`/g, '<code>$1</code>');
            html = html.replace(/\*\*([^*]+)\*\*/g, '<strong style="color: var(--green-bright);">$1</strong>');
            html = html.replace(/\n/g, '<br>');
            bub.innerHTML = html;
            scrollToBottom();
        }

        function finishMessage() {
            hideThinking();
            if (currentMessageDiv) {
                saveCurrentChatMessages();
                currentMessageDiv = null;
                messageBuffer = '';
            }
        }

        function renderCodeBlock(lang, code, complete) {
            const copyBtnClass = 'code-btn copy';
            const downloadBtnClass = 'code-btn download';
            const applyBtnClass = 'code-btn apply';
            const lineCount = (code.match(/\n/g) || []).length + 1;
            const shouldCollapse = complete; // всегда свёрнут по умолчанию
            const collapsedClass = shouldCollapse ? 'collapsed' : '';
            const toggleBtn = complete
                ? `<button class="code-btn toggle" onclick="toggleCodeBlock(this)" title="Развернуть/свернуть">${shouldCollapse ? '▶' : '▼'}</button>`
                : '';
            const linesHint = complete
                ? `<span class="code-lines-hint">${lineCount} lines</span>`
                : '';
            const actions = complete ? `
                <div class="code-actions">
                    ${toggleBtn}
                    <button class="${copyBtnClass}" onclick="copyCodeFromBlock(this)" title="Копировать">◈</button>
                    <button class="${downloadBtnClass}" onclick="downloadCodeFromBlock(this)" title="Скачать">↓</button>
                    ${lang === 'json' ? `<button class="${applyBtnClass}" onclick="preparePatchFromBlock(this)" title="Применить патч">△</button>` : ''}
                </div>
            ` : '';
            return `
                <div class="code-block ${complete ? 'complete' : 'streaming'} ${collapsedClass}">
                    <div class="code-header">
                        <span class="code-lang">${lang || 'code'}</span>
                        ${linesHint}
                        ${actions}
                    </div>
                    <pre class="code-content">${escapeHtml(code)}</pre>
                </div>
            `;
        }

        window.toggleCodeBlock = function(btn) {
            const block = btn.closest('.code-block');
            const isCollapsed = block.classList.toggle('collapsed');
            btn.innerHTML = isCollapsed ? '▶' : '▼';
        };

        // Декодирование HTML-сущностей
        function decodeHtmlEntities(text) {
            const textarea = document.createElement('textarea');
            textarea.innerHTML = text;
            return textarea.value;
        }

        window.downloadCodeFromBlock = function(btn) {
            const block = btn.closest('.code-block');
            const rawCode = block.querySelector('.code-content').textContent;
            const decodedCode = decodeHtmlEntities(rawCode);
            const lang = block.querySelector('.code-lang').textContent || 'txt';
            const blob = new Blob([decodedCode], { type: 'text/plain' });
            const url = URL.createObjectURL(blob);
            const a = document.createElement('a');
            a.href = url;
            a.download = `code.${lang}`;
            a.click();
            URL.revokeObjectURL(url);
            showToast('◈ файл скачан', 'success');
        };

        window.copyCodeFromBlock = function(btn) {
            const block = btn.closest('.code-block');
            // Используем innerText вместо textContent + decodeHtmlEntities
            // innerText корректно сохраняет переносы строк из <pre>
            const code = block.querySelector('.code-content').innerText;
            navigator.clipboard.writeText(code).then(() => {
                const originalText = btn.innerHTML;
                btn.innerHTML = '✓';
                showToast('◈ код скопирован', 'success');
                setTimeout(() => {
                    btn.innerHTML = originalText;
                }, 1000);
            }).catch(err => {
                showToast('◈ ошибка копирования', 'error');
                console.error('Copy failed:', err);
            });
        };

        window.preparePatchFromBlock = function(btn) {
            const codeElement = btn.closest('.code-block').querySelector('.code-content');
            const rawCode = codeElement.textContent;
            const decodedCode = decodeHtmlEntities(rawCode);
            try {
                JSON.parse(decodedCode);
                currentPatch = decodedCode;
                document.getElementById('patchPreviewContent').textContent = decodedCode;
                document.getElementById('confirmPatchBtn').disabled = false;
                openPatchModal();
                showToast('◈ патч подготовлен', 'success');
            } catch(e) {
                showToast('◈ невалидный JSON: ' + e.message, 'error');
            }
        };

        // ==================== ОТПРАВКА СООБЩЕНИЙ ====================
        function sendMessage() {
            const text = inputEl.value.trim();
            if (pendingFiles.length > 0) {
                sendFiles(pendingFiles, text);
                clearFiles();
                inputEl.value = '';
                autoHeight();
                return;
            }
            if (!text) return;
            addUserMessage(text);
            inputEl.value = '';
            autoHeight();
            showThinking();
            if (!ws || ws.readyState !== WebSocket.OPEN) {
                showToast('◈ нет соединения с сервером', 'error');
                hideThinking();
                return;
            }
            ws.send(JSON.stringify({ type: 'ask', text: text, session_id: currentChatId }));
        }

        async function sendFiles(files, caption) {
            if (!ws || ws.readyState !== WebSocket.OPEN) {
                showToast('◈ нет соединения', 'error');
                return;
            }
            if (caption.trim()) addUserMessage(caption);
            showThinking();

            // Показываем индикатор загрузки
            filePreview.classList.remove('hidden');
            fileProgressBar.style.width = '0%';
            filePercentEl.textContent = '0%';

            let completed = 0;
            for (const file of files) {
                // Обновляем имя текущего файла
                fileNameEl.textContent = `⏳ ${file.name}`;

                await new Promise((resolve) => {
                    const reader = new FileReader();
                    reader.onload = function(e) {
                        ws.send(JSON.stringify({
                            type: 'file',
                            name: file.name,
                            content: e.target.result.split(',')[1],
                            file_type: file.type || 'application/octet-stream',
                            caption: '',
                            session_id: currentChatId
                        }));
                        completed++;
                        const percent = Math.round((completed / files.length) * 100);
                        fileProgressBar.style.width = percent + '%';
                        filePercentEl.textContent = percent + '%';
                        resolve();
                    };
                    reader.readAsDataURL(file);
                });
                await new Promise(r => setTimeout(r, 100));
            }

            // Показываем "ожидаем подтверждения от сервера"
            fileNameEl.textContent = `✓ ${files.map(f => f.name).join(', ')}`;
            saveCurrentChatMessages();

            // Прячем через 4 сек (к этому времени file_processed уже придёт)
            setTimeout(() => {
                filePreview.classList.add('hidden');
                fileProgressBar.style.width = '0%';
                filePercentEl.textContent = '0%';
            }, 4000);
        }

        // ==================== ФАЙЛЫ ====================
        function handleFileSelect(e) {
            const files = Array.from(e.target.files);
            if (files.length === 0) return;
            pendingFiles = files;
            updateFilePreview();
            inputEl.focus();
        }

        function updateFilePreview() {
            if (pendingFiles.length === 0) {
                filePreview.classList.add('hidden');
                return;
            }
            const names = pendingFiles.map(f => f.name).join(', ');
            fileNameEl.textContent = names;
            filePreview.classList.remove('hidden');
            fileProgressBar.style.width = '0%';
            filePercentEl.textContent = '0%';
        }

        function clearFiles() {
            pendingFiles = [];
            document.getElementById('fileInput').value = '';
            // Не прячем filePreview здесь — он скроется сам после подтверждения сервера
        }

        function setupDragDrop() {
            document.addEventListener('dragover', e => { e.preventDefault(); document.body.style.boxShadow = 'inset 0 0 50px var(--violet-dim)'; });
            document.addEventListener('dragleave', e => { if(e.target===document.body) document.body.style.boxShadow = ''; });
            document.addEventListener('drop', e => {
                e.preventDefault();
                document.body.style.boxShadow = '';
                const files = Array.from(e.dataTransfer.files);
                if (files.length > 0) {
                    pendingFiles = files;
                    updateFilePreview();
                    inputEl.focus();
                }
            });
        }

        // ==================== ВКЛАДКА ФАЙЛОВ ====================
        async function loadFileTree() {
            fileTree.innerHTML = 'Загрузка...';
            try {
                const response = await fetch(`${API_BASE}/api/tree`);
                if (!response.ok) {
                    throw new Error(`HTTP ${response.status}`);
                }
                const data = await response.json();
                if (data.error) throw new Error(data.error);
                const tree = buildTree(data.tree);
                fileTree.innerHTML = renderTree(tree);
                document.querySelectorAll('#file-tree .file').forEach(el => {
                    el.addEventListener('click', () => {
                        document.querySelectorAll('#file-tree .file').forEach(f => f.classList.remove('selected'));
                        el.classList.add('selected');
                        loadFile(el.dataset.path);
                    });
                });
            } catch (err) {
                fileTree.innerHTML = `❌ Ошибка загрузки: ${err.message}`;
            }
        }

        function buildTree(files) {
            const root = {};
            files.forEach(file => {
                if (file.type !== 'blob') return;
                const parts = file.path.split('/');
                let current = root;
                parts.forEach((part, i) => {
                    if (i === parts.length - 1) {
                        current[part] = { type: 'file', path: file.path };
                    } else {
                        if (!current[part]) current[part] = { type: 'dir', children: {} };
                        current = current[part].children;
                    }
                });
            });
            return root;
        }

        function renderTree(node, level = 0) {
            if (node.type === 'file') {
                const ext = node.path.split('.').pop();
                return `<div class="file file ${ext}" data-path="${node.path}" style="padding-left: ${level * 16 + 16}px">${node.path.split('/').pop()}</div>`;
            }
            let html = '';
            Object.keys(node).forEach(key => {
                if (key === 'type') return;
                const child = node[key];
                if (child.type === 'dir') {
                    html += `<div class="folder" style="padding-left: ${level * 16}px">${key}</div>`;
                    html += renderTree(child.children, level + 1);
                } else {
                    html += renderTree(child, level + 1);
                }
            });
            return html;
        }

        async function loadFile(path) {
            currentFilePath.textContent = path;
            saveFileBtn.disabled = false;
            try {
                const response = await fetch(`https://raw.githubusercontent.com/${GITHUB_REPO}/main/${path}`);
                if (!response.ok) throw new Error(`HTTP ${response.status}`);
                const content = await response.text();
                const ext = path.split('.').pop();
                const language = ext === 'json' ? 'json' : ext === 'py' ? 'python' : ext === 'html' ? 'html' : ext === 'js' ? 'javascript' : 'text';
                monaco.editor.setModelLanguage(editor.getModel(), language);
                editor.setValue(content);
                localStorage.setItem(`orig_${path}`, content);
                // Уведомляем СР об открытом файле
                addSystemMessage(`📁 Открыт файл: ${path}`, true);
            } catch (err) {
                editor.setValue(`// Ошибка загрузки: ${err.message}`);
            }
        }

        function saveCurrentFile() {
            const path = currentFilePath.textContent;
            if (!path) return;
            const content = editor.getValue();
            const patch = { file_path: path, content: content };
            if (ws && ws.readyState === WebSocket.OPEN) {
                ws.send(JSON.stringify({ type: 'apply_patch', patch: patch, session_id: currentChatId }));
                showToast('◈ изменения отправлены', 'success');
                localStorage.setItem(`orig_${path}`, content);
            } else {
                showToast('◈ нет соединения', 'error');
            }
        }

        // ==================== УТИЛИТЫ ====================
        function escapeHtml(text) {
            const div = document.createElement('div');
            div.textContent = text;
            return div.innerHTML;
        }

        function showThinking() {
            thinkingEl.classList.remove('hidden');
            scrollToBottom();
        }

        function hideThinking() {
            thinkingEl.classList.add('hidden');
        }

        function scrollToBottom() {
            messagesEl.scrollTop = messagesEl.scrollHeight;
        }

        function autoHeight() {
            inputEl.style.height = 'auto';
            inputEl.style.height = inputEl.scrollHeight + 'px';
        }

        function updateResonance(value, level) {
            const indicator = document.getElementById('resonanceIndicator');
            const fill = document.getElementById('resonanceFill');
            const valueEl = document.getElementById('resonanceValue');
            if (!indicator || !fill || !valueEl) return;
            indicator.classList.add('visible');
            const percentage = Math.round(value * 100);
            valueEl.textContent = `${percentage}%`;
            fill.style.width = `${percentage}%`;
            indicator.className = 'resonance-indicator visible resonance-level-' + level;
            setTimeout(() => indicator.classList.remove('visible'), 8000);
        }

        // ==================== CLAUDE-НАБЛЮДАТЕЛЬ ====================
        let observerActive = false;
        let observerThinkingEl = null;

        function toggleObserver() {
            if (!ws || ws.readyState !== WebSocket.OPEN) {
                showToast('◬ нет соединения', 'error');
                return;
            }
            ws.send(JSON.stringify({ type: 'toggle_observer', session_id: currentChatId }));
        }

        function setObserverState(active) {
            observerActive = active;
            const btn = document.getElementById('observerBtn');
            if (active) {
                btn.classList.add('active');
                btn.title = 'Claude-наблюдатель активен (нажми чтобы выключить)';
                showToast('◬ Claude-наблюдатель подключён', 'success');
            } else {
                btn.classList.remove('active');
                btn.title = 'Claude-наблюдатель (нажми чтобы включить)';
                showToast('◬ Claude-наблюдатель отключён', 'error');
            }
        }

        function showObserverThinking() {
            hideObserverThinking();
            observerThinkingEl = document.createElement('div');
            observerThinkingEl.className = 'observer-thinking-indicator';
            observerThinkingEl.innerHTML = `
                <span>◬</span>
                <span class="dots"><span>claude анализирует...</span></span>
            `;
            messagesEl.appendChild(observerThinkingEl);
            scrollToBottom();
        }

        function hideObserverThinking() {
            if (observerThinkingEl) {
                observerThinkingEl.remove();
                observerThinkingEl = null;
            }
        }

        function addObserverMessage(text) {
            const div = document.createElement('div');
            div.className = 'msg observer';
            // Иконка Claude в стиле Мандалы — треугольник с кругом
            const iconSvg = `<svg viewBox="0 0 30 30" fill="none">
                <polygon points="15,3 27,24 3,24" stroke="#3b82f6" stroke-width="0.8" fill="rgba(59,130,246,0.06)"/>
                <polygon points="15,8 22,21 8,21" stroke="#6366f1" stroke-width="0.8" opacity="0.6" fill="none"/>
                <circle cx="15" cy="15" r="2" fill="#60a5fa" opacity="0.9"/>
            </svg>`;
            let html = escapeHtml(text);
            html = html.replace(/```(\w*)\n([\s\S]*?)```/g, (match, lang, code) => renderCodeBlock(lang, code, true));
            html = html.replace(/`([^`]+)`/g, '<code>$1</code>');
            html = html.replace(/\*\*([^*]+)\*\*/g, '<strong style="color:#60a5fa;">$1</strong>');
            html = html.replace(/\n/g, '<br>');
            div.innerHTML = `
                <div class="av">${iconSvg}</div>
                <div class="mbody">
                    <div class="mname">Claude ◬</div>
                    <div class="bub">${html}</div>
                </div>
            `;
            messagesEl.appendChild(div);
            scrollToBottom();
            saveCurrentChatMessages();
        }

        function setupKeyboard() {
            inputEl.addEventListener('keydown', e => {
                if (e.key === 'Enter' && !e.shiftKey) {
                    e.preventDefault();
                    sendMessage();
                }
            });
            inputEl.addEventListener('input', autoHeight);
        }

        function setupTabs() {
            document.querySelectorAll('.tab').forEach(tab => {
                tab.addEventListener('click', () => {
                    const tabName = tab.dataset.tab;
                    document.querySelectorAll('.tab').forEach(t => t.classList.remove('active'));
                    tab.classList.add('active');
                    document.querySelectorAll('.tab-content').forEach(c => c.classList.remove('active'));
                    document.getElementById(`tab-${tabName}`).classList.add('active');
                    if (tabName === 'status') loadStatus();
                    if (tabName === 'files') loadFileTree();
                });
            });
        }

        async function loadStatus() {
            seedsGrid.innerHTML = '<div class="empty-state"><div class="empty-state-icon">○</div><div>загрузка...</div></div>';
            document.getElementById('roadmapsGrid').innerHTML = '<div class="empty-state"><div class="empty-state-icon">○</div><div>загрузка...</div></div>';
            document.getElementById('statusRings').innerHTML = '';

            // Карточки колец
            const rings = [
                { name: 'Crystal', color: 'var(--indigo-soft)', desc: 'initium · philosophia · geometria' },
                { name: 'Flow', color: 'var(--green-2)', desc: 'akasha · incubae · sphaerae' },
                { name: 'Impulse', color: 'var(--violet-soft)', desc: 'tectosphaera' }
            ];
            document.getElementById('statusRings').innerHTML = rings.map(r => `
                <div style="flex:1;min-width:140px;padding:10px 12px;background:var(--surface);border:1px solid var(--line-2);border-radius:var(--radius);border-left:2px solid ${r.color};">
                    <div style="font-family:var(--mono);font-size:10px;color:${r.color};letter-spacing:1px;margin-bottom:4px;">${r.name}</div>
                    <div style="font-family:var(--mono);font-size:9px;color:var(--text-2);">${r.desc}</div>
                </div>
            `).join('');

            // ── Семена ──
            try {
                const incResp = await fetch(`https://raw.githubusercontent.com/${GITHUB_REPO}/main/incubae.json`);
                if (!incResp.ok) throw new Error(`HTTP ${incResp.status}`);
                const incData = await incResp.json();

                // fast_index может лежать как 'fast_index' или '/fast_index'
                const fastIndex = incData['fast_index'] || incData['/fast_index'] || {};
                const fastSeeds = fastIndex.seeds || [];
                const directSeeds = incData.seeds || [];

                // Предпочитаем полные данные из seeds, дополняем fast_index
                const allSeeds = directSeeds.length ? directSeeds : fastSeeds;
                const totalActive = fastIndex.total_active || fastSeeds.filter(s => s.status === 'active').length || allSeeds.length;

                // Счётчик — одна строка
                const seedLabel = document.getElementById('seedsLabel');
                if (seedLabel) seedLabel.textContent = `🌱 семена (incubae) — ${totalActive} активных`;

                if (!allSeeds.length) {
                    seedsGrid.innerHTML = '<div class="empty-state"><div class="empty-state-icon">○</div><div>нет семян</div></div>';
                } else {
                    seedsGrid.innerHTML = allSeeds.map(seed => `
                        <div class="seed-card" onclick="askAboutSeed('${seed.id}')">
                            <div class="seed-header">
                                <div class="seed-title">${escapeHtml(seed.name || seed.id || 'без названия')}</div>
                                <div class="seed-id">${seed.id || ''}</div>
                            </div>
                            <div class="seed-desc">${escapeHtml(seed.description || seed.core_essence || '')}</div>
                            <div class="seed-meta">
                                <span class="seed-badge" style="border-color:var(--green);color:var(--green-bright);">${seed.type || 'seed'}</span>
                                <span class="seed-badge" style="border-color:${seed.status==='active'?'var(--green)':'var(--text-3)'};">${seed.status || 'active'}</span>
                                ${seed.expiry ? `<span class="seed-badge">до ${seed.expiry}</span>` : ''}
                            </div>
                        </div>
                    `).join('');
                }
            } catch(err) {
                seedsGrid.innerHTML = `<div class="empty-state"><div class="empty-state-icon">×</div><div>${err.message}</div></div>`;
            }

            // ── Роадмапы ──
            const rmGrid = document.getElementById('roadmapsGrid');
            try {
                const akResp = await fetch(`https://raw.githubusercontent.com/${GITHUB_REPO}/main/akasha_chronicorum.json`);
                if (!akResp.ok) throw new Error(`HTTP ${akResp.status}`);
                const akData = await akResp.json();

                // fast_index или прямой поиск в spheres.cosmosphaera.blocks
                const fi = akData['fast_index'] || akData['/fast_index'] || {};
                let roadmaps = fi.roadmaps || [];

                if (!roadmaps.length) {
                    // Ищем в spheres.cosmosphaera.blocks (реальная структура)
                    const cosmo = (akData.spheres || {}).cosmosphaera || akData.cosmosphaera || {};
                    const blocks = cosmo.blocks || [];
                    const rmBlocks = blocks.filter(b => b && (b.type === 'roadmap' || b.roadmap));
                    roadmaps = rmBlocks.map(b => ({
                        id: b.id || '?',
                        title: (b.roadmap || {}).title || (b.roadmap || {}).description || b.id || 'Роадмап',
                        description: (b.roadmap || {}).description || '',
                        milestones: ((b.roadmap || {}).milestones || []).length,
                        status: b.status || 'active'
                    }));
                }

                // Счётчик — одна строка
                const rmLabel = document.getElementById('roadmapsLabel');
                if (rmLabel) rmLabel.textContent = `📜 роадмапы (akasha) — ${roadmaps.length}`;

                if (!roadmaps.length) {
                    rmGrid.innerHTML = '<div class="empty-state"><div class="empty-state-icon">○</div><div>нет роадмапов</div></div>';
                } else {
                    rmGrid.innerHTML = roadmaps.map(rm => `
                        <div class="seed-card" style="border-left:2px solid var(--violet-soft);">
                            <div class="seed-header">
                                <div class="seed-title">${escapeHtml(rm.title)}</div>
                                <div class="seed-id">${rm.id}</div>
                            </div>
                            <div class="seed-desc">${escapeHtml(rm.description)}</div>
                            <div class="seed-meta">
                                <span class="seed-badge" style="border-color:var(--violet-soft);color:var(--violet-soft);">roadmap</span>
                                ${rm.milestones ? `<span class="seed-badge">${rm.milestones} milestones</span>` : ''}
                                <span class="seed-badge">${rm.status}</span>
                            </div>
                        </div>
                    `).join('');
                }
            } catch(err) {
                rmGrid.innerHTML = `<div class="empty-state"><div class="empty-state-icon">×</div><div>${err.message}</div></div>`;
            }
        }

        // Оставляем loadSeeds как alias
        async function loadSeeds() { return loadStatus(); }

        window.askAboutSeed = (seedId) => sendDirectMessage(`Расскажи о семени ${seedId}`);

        // ==================== ПАТЧИ ====================
        function openPatchModal() { document.getElementById('patchModal').classList.add('active'); }
        function closePatchModal() {
            document.getElementById('patchModal').classList.remove('active');
            currentPatch = null;
            document.getElementById('confirmPatchBtn').disabled = true;
            document.getElementById('patchPreviewContent').textContent = 'загрузите JSON-патч...';
        }
        function confirmPatch() {
            if (!currentPatch || !ws || ws.readyState !== WebSocket.OPEN) return;
            try {
                ws.send(JSON.stringify({ type: 'apply_patch', patch: JSON.parse(currentPatch), session_id: currentChatId }));
                closePatchModal();
                showToast('◈ патч отправлен', 'success');
                addSystemMessage('◈ применение патча...');
            } catch(e) {
                showToast('◈ ошибка патча', 'error');
            }
        }
        function handlePatchResult(results) {
            results.forEach(r => addSystemMessage(`◈ ${r.status==='success'?'✓':'✗'} ${r.file||r.module}: ${r.message}`));
        }

        // ==================== БЫСТРЫЕ ДЕЙСТВИЯ ====================
        function quickAction(action) {
            if (action === 'files') sendDirectMessage('/tree');
            else if (action === 'forget') {
                if (confirm('Очистить историю этого чата?')) {
                    messagesEl.innerHTML = '';
                    addSystemMessage('◈ история забыта');
                    saveCurrentChatMessages();
                }
            }
        }

        function sendDirectMessage(text) {
            if (!ws || ws.readyState !== WebSocket.OPEN) {
                showToast('◈ нет соединения', 'error');
                return;
            }
            addUserMessage(text);
            showThinking();
            ws.send(JSON.stringify({ type: 'ask', text: text, session_id: currentChatId }));
        }

        // ==================== TOAST ====================
        function showToast(msg, type='success') {
            const toast = document.getElementById('toast');
            toast.textContent = msg;
            toast.className = `toast ${type} show`;
            setTimeout(() => toast.classList.remove('show'), 3000);
        }

        // ==================== АНИМАЦИЯ ЦВЕТКА ЖИЗНИ ====================
        function animateFlowerGradient() {
            const grad = document.getElementById('livingGradient');
            if (!grad) return;
            let angle = 0;
            function step() {
                angle += 0.005;
                const x = 0.5 + 0.5 * Math.sin(angle);
                const y = 0.5 + 0.5 * Math.cos(angle);
                grad.setAttribute('x1', x);
                grad.setAttribute('y1', y);
                grad.setAttribute('x2', 1 - x);
                grad.setAttribute('y2', 1 - y);
                requestAnimationFrame(step);
            }
            step();
        }

        // ==================== ЗАПУСК ====================
        function init() {
            loadChats();
            if (chats.length === 0) createNewChat('Основной чат');
            else {
                const lastActive = localStorage.getItem('current_chat_id');
                if (lastActive && chats.find(c => c.id === lastActive)) switchChat(lastActive);
                else switchChat(chats[0].id);
            }
            connect();
            setupTabs();
            setupKeyboard();
            setupDragDrop();
            animateFlowerGradient();
        }

        init();
    </script>
</body>
</html>

